int main(){try{unsigned cases=0;for(const auto&row:nativeCases){const float dx=std::bit_cast<float>(row[2]),dz=std::bit_cast<float>(row[3]);const long double squared=static_cast<long double>(dx)*dx+static_cast<long double>(dz)*dz;const float amount=nativeAmmoRadialDamage(std::bit_cast<float>(row[0]),row[1],squared);if(std::bit_cast<uint32_t>(amount)!=row[4])throw std::runtime_error("native radial amount mismatch case="+std::to_string(cases));++cases;}
 const auto need=[](bool b,const char*s){if(!b)throw std::runtime_error(s);};
 need(nativeAmmoRadialDamage(100,30,899.999L)==100.f/30,"strict truncated squared-distance boundary inside");
 need(nativeAmmoRadialDamage(100,30,900)==0,"exact squared radius boundary excluded");
 need(nativeAmmoRadialDamage(100,30,.999L)==100,"sub-unit squared distance gives full damage");
 need(nativeAmmoRadialDamage(100,30.9f,0)==100&&nativeAmmoRadialDamage(100,30.9f,900)==0,"authored radius enters integer field");
 need(nativeAmmoRadialDamage(100,0,0)==0&&nativeAmmoRadialDamage(0,30,0)==0,"zero radius/damage no radial operation");
 need(nativeAmmoRadialDamage(100,-1,0)==0&&nativeAmmoRadialDamage(100,50000,0)==0,"invalid radii safely rejected");
 need(nativeAmmoRadialDamage(100,30,-1)==0&&nativeAmmoRadialDamage(100,30,std::numeric_limits<long double>::infinity())==0,"invalid distance safely rejected");
 need(nativeAmmoRadialDamage(std::numeric_limits<float>::quiet_NaN(),30,0)==0,"invalid damage safely rejected");
 std::cout<<"native radial scalar64 original argument fixtures and range/default controls passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
